// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { c = new PoCGame(address(this), 0); }

    function testFuzz_property(uint256 initial, uint256 delta) public {
        initial = bound(initial, 1, type(uint64).max);
        delta = bound(delta, 0, type(uint64).max);

        c.AdjustBetAmounts(initial);
        assertTrue(c.currentBetLimit() == initial);

        c.AdjustBetAmounts(delta);

        assertTrue(c.currentBetLimit() == delta);
    }
}
